-- Schema inicial do GymVis no Postgres (Supabase).
--
-- Convenções mantidas da versão SQLite para que a migração não altere nenhuma
-- métrica: dinheiro em centavos (integer), instantes em epoch ms (bigint) e
-- datas de calendário como texto 'YYYY-MM-DD' (ordena igual a date).
--
-- As chaves usam GENERATED BY DEFAULT (e não ALWAYS) porque a importação dos
-- dados existentes insere ids explícitos; as sequências são ajustadas depois.

create table if not exists academies (
  id          bigint generated by default as identity primary key,
  nome        text   not null,
  created_at  bigint not null
);

create table if not exists users (
  id             bigint generated by default as identity primary key,
  academy_id     bigint not null references academies(id),
  nome           text   not null,
  email          text   not null,
  password_hash  text   not null,
  created_at     bigint not null
);
create unique index if not exists users_email_unique on users(email);

create table if not exists sessions (
  token       text   primary key,
  user_id     bigint not null references users(id),
  created_at  bigint not null,
  expires_at  bigint not null
);
create index if not exists sessions_user_idx on sessions(user_id);

create table if not exists plans (
  id             bigint  generated by default as identity primary key,
  academy_id     bigint  not null references academies(id),
  nome           text    not null,
  valor_centavos integer not null,
  duracao_meses  integer not null default 1
);
create index if not exists plans_academy_idx on plans(academy_id);

create table if not exists promotions (
  id                bigint  generated by default as identity primary key,
  academy_id        bigint  not null references academies(id),
  nome              text    not null,
  desconto_centavos integer not null default 0,
  ativa             boolean not null default true,
  created_at        bigint  not null
);
create index if not exists promotions_academy_idx on promotions(academy_id);

create table if not exists students (
  id                    bigint  generated by default as identity primary key,
  academy_id            bigint  not null references academies(id),
  plano_id              bigint  not null references plans(id),
  promocao_id           bigint  references promotions(id),
  nome                  text    not null,
  email                 text,
  telefone              text,
  data_entrada          text    not null,
  data_saida            text,
  status                text    not null,
  mensalidade_centavos  integer not null
);
create index if not exists students_academy_idx on students(academy_id);
create index if not exists students_academy_status_idx on students(academy_id, status);

create table if not exists access_events (
  id          bigint generated by default as identity primary key,
  academy_id  bigint not null references academies(id),
  aluno_id    bigint not null references students(id),
  "timestamp" bigint not null,
  tipo_evento text   not null default 'entrada'
);
create index if not exists access_aluno_ts_idx on access_events(aluno_id, "timestamp");
create index if not exists access_academy_ts_idx on access_events(academy_id, "timestamp");

create table if not exists expenses (
  id             bigint  generated by default as identity primary key,
  academy_id     bigint  not null references academies(id),
  descricao      text    not null,
  categoria      text    not null,
  valor_centavos integer not null,
  data           text    not null,
  created_at     bigint  not null
);
create index if not exists expenses_academy_data_idx on expenses(academy_id, data);

create table if not exists academy_settings (
  academy_id            bigint primary key references academies(id),
  inactivity_medium     integer not null,
  inactivity_high       integer not null,
  inactivity_critical   integer not null,
  frequency_drop_medium real    not null,
  frequency_drop_high   real    not null,
  updated_at            bigint  not null
);

-- ---------------------------------------------------------------------------
-- Row Level Security.
--
-- O Supabase publica toda tabela do schema public via PostgREST. Sem RLS,
-- qualquer pessoa com a chave anon — que é pública por natureza — leria o
-- cadastro, o telefone e a frequência de todos os alunos.
--
-- Ligar RLS SEM criar policy nenhuma nega tudo para anon e authenticated. O
-- servidor do GymVis conecta como o papel do banco (não via PostgREST), que
-- não é submetido a RLS, e continua fazendo o isolamento por academy_id em
-- cada consulta. Ou seja: RLS aqui é a segunda linha de defesa, fechando o
-- acesso pela borda pública.
-- ---------------------------------------------------------------------------

alter table academies        enable row level security;
alter table users            enable row level security;
alter table sessions         enable row level security;
alter table plans            enable row level security;
alter table promotions       enable row level security;
alter table students         enable row level security;
alter table access_events    enable row level security;
alter table expenses         enable row level security;
alter table academy_settings enable row level security;

-- Revoga também o acesso direto dos papéis expostos pela API, para o caso de
-- alguém criar uma policy permissiva por engano no futuro.
revoke all on all tables in schema public from anon, authenticated;
